SELECT channel, period, SUM(net_cents)/100.0 AS net_sales, COUNT(DISTINCT order_id) AS order_count, (SUM(net_cents)/100.0)/COUNT(DISTINCT order_id) AS aov, SUM(pre_refund_cents)/100.0 AS pre_refund_sales, SUM(refund_amount_cents)/100.0 AS refund_amount, SUM(refund_amount_cents)/NULLIF(SUM(pre_refund_cents),0) AS refund_rate FROM items WHERE period IN ('control','analysis') AND channel='App' GROUP BY channel, period ORDER BY period;